#!/usr/bin/env python3
"""Audit services/ against SPEC.md rev 7 plus amendment 1 (C16)."""
import ast
import json
import re
import sys
from pathlib import Path

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else "services")
OUT = Path(sys.argv[2]) if len(sys.argv) > 2 else None
LFS_FIRST = "version https://git-lfs.github.com/spec/v1"
CLAUSES = [f"C{i}" for i in range(1, 17)]


def files(service):
    return sorted(p for p in service.rglob("*") if p.is_file())


def is_pointer(path):
    try:
        with path.open("rb") as fh:
            first = fh.readline().decode("utf-8", "replace").rstrip("\r\n")
        return first == LFS_FIRST
    except OSError:
        return False


def py_under_src(service):
    return sorted(p for p in (service / "src").rglob("*.py") if p.is_file())


def parse_py(path):
    return ast.parse(path.read_text(encoding="utf-8"))


def check_c1(cfg):
    return not (cfg.get("exposure") == "public" and
                (not isinstance(cfg.get("timeout_s"), (int, float)) or
                 isinstance(cfg.get("timeout_s"), bool) or
                 cfg["timeout_s"] > 30))


def check_c2(service):
    path = service / "src" / "handlers.py"
    tree = parse_py(path)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if node.name.startswith("handle_") and ast.get_docstring(node) is None:
                return False
    return True


def check_c3(service):
    for path in py_under_src(service):
        for node in ast.walk(parse_py(path)):
            if (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                    and node.func.id == "print"):
                return False
    return True


def check_c4(cfg):
    r = cfg.get("retries")
    return isinstance(r, int) and not isinstance(r, bool) and 1 <= r <= 5


FROM_RE = re.compile(r"^FROM\s+(?:--\S+\s+)*(\S+)(?:\s+AS\s+\S+)?\s*$", re.I)
DIGEST_RE = re.compile(r"@sha256:[0-9a-f]{64}$")


def dockerfile_from_images(service):
    images = []
    for line in (service / "Dockerfile").read_text(encoding="utf-8").splitlines():
        if line.lstrip().upper().startswith("FROM "):
            m = FROM_RE.match(line.strip())
            if m:
                images.append(m.group(1))
    return images


def check_c5(service):
    images = dockerfile_from_images(service)
    return bool(images) and all(DIGEST_RE.search(i) for i in images)


def check_c6(service):
    users = []
    for line in (service / "Dockerfile").read_text(encoding="utf-8").splitlines():
        s = line.strip()
        if s.upper().startswith("USER "):
            users.append(s.split(None, 1)[1].strip())
    if not users:
        return False
    last = users[-1].split()[0]
    return last.split(":")[0] not in ("root", "0")


def check_c7(service):
    lines = (service / "README.md").read_text(encoding="utf-8").splitlines()
    return any(line == "## Runbook" for line in lines)


def check_c8(service, cfg):
    want = "@team-" + str(cfg.get("team", ""))
    for line in (service / "CODEOWNERS").read_text(encoding="utf-8").splitlines():
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        fields = s.split()
        if fields[0] == "*" and want in fields[1:]:
            return True
    return False


def check_c9(service):
    for path in py_under_src(service):
        tree = parse_py(path)
        for node in ast.walk(tree):
            vals = []
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                vals.append(node.value)
            elif isinstance(node, ast.JoinedStr):
                vals.extend(v.value for v in node.values
                            if isinstance(v, ast.Constant) and isinstance(v.value, str))
            if any(v.startswith(("sk_live_", "AKIA")) for v in vals):
                return False
    return True


def check_c10(service, cfg):
    hc = cfg.get("healthcheck")
    if not isinstance(hc, str) or not hc:
        return False
    segment = hc.split("?", 1)[0].rstrip("/").rsplit("/", 1)[-1]
    if not segment:
        return False
    defined = set()
    for node in ast.walk(parse_py(service / "src" / "handlers.py")):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            defined.add(node.name)
    return "handle_" + segment in defined


def check_c11(cfg):
    return cfg.get("metrics_port") != cfg.get("port")


def req_pinned(line):
    s = line.split("#", 1)[0].strip()
    if not s:
        return True
    m = re.match(r"^[A-Za-z0-9][A-Za-z0-9._-]*(?:\[[^\]]+\])?=="
                 r"[A-Za-z0-9][A-Za-z0-9.*+!_-]*$", s)
    return bool(m)


def check_c12(service):
    return all(req_pinned(line) for line in
               (service / "requirements.txt").read_text(encoding="utf-8").splitlines())


def check_c13(cfg):
    return cfg.get("log_level") != "DEBUG"


def check_c14(cfg):
    m = cfg.get("max_body_kb")
    return not (cfg.get("exposure") == "public" and
                (not isinstance(m, (int, float)) or isinstance(m, bool) or m > 1024))


def check_c15(service):
    tests = service / "tests"
    return tests.is_dir() and any(
        p.is_file() and p.name.startswith("test_") and p.name.endswith(".py")
        for p in tests.rglob("*"))


def check_c16(cfg):
    r = cfg.get("rate_limit_rps")
    return not (cfg.get("exposure") == "public" and
                (not isinstance(r, int) or isinstance(r, bool) or not 1 <= r <= 10000))


def audit(service):
    all_files = files(service)
    if any(is_pointer(p) for p in all_files):
        return {"service": service.name, "status": "unverifiable", "violations": []}
    cfg = json.loads((service / "config.json").read_text(encoding="utf-8"))
    checks = {
        "C1": lambda: check_c1(cfg),
        "C2": lambda: check_c2(service),
        "C3": lambda: check_c3(service),
        "C4": lambda: check_c4(cfg),
        "C5": lambda: check_c5(service),
        "C6": lambda: check_c6(service),
        "C7": lambda: check_c7(service),
        "C8": lambda: check_c8(service, cfg),
        "C9": lambda: check_c9(service),
        "C10": lambda: check_c10(service, cfg),
        "C11": lambda: check_c11(cfg),
        "C12": lambda: check_c12(service),
        "C13": lambda: check_c13(cfg),
        "C14": lambda: check_c14(cfg),
        "C15": lambda: check_c15(service),
        "C16": lambda: check_c16(cfg),
    }
    bad = [c for c in CLAUSES if not checks[c]()]
    return {"service": service.name,
            "status": "violations" if bad else "compliant",
            "violations": bad}


def main():
    reports = [audit(s) for s in sorted(p for p in ROOT.iterdir() if p.is_dir())]
    for r in reports:
        line = json.dumps(r, separators=(", ", ": "))
        print(line)
        if OUT:
            OUT.mkdir(parents=True, exist_ok=True)
            (OUT / f"{r['service']}.json").write_text(line + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

