#!/usr/bin/env python3
import hashlib
import time
from pathlib import Path

root = Path(".")
targets = lambda: sorted(
    p for p in list(Path("services").rglob("*")) + list(Path(".").glob("SPEC*.md"))
    if p.is_file())
prev = {}
while True:
    cur = {}
    for p in targets():
        try:
            cur[str(p)] = hashlib.sha256(p.read_bytes()).hexdigest()
        except OSError:
            cur[str(p)] = "MISSING"
    if prev and cur != prev:
        changed = [k for k in set(cur) | set(prev) if cur.get(k) != prev.get(k)]
        print(time.strftime("%H:%M:%S"), "CHANGE", " ".join(sorted(changed)), flush=True)
        prev = cur
    elif not prev:
        prev = cur
        print(time.strftime("%H:%M:%S"), "WATCHING", len(cur), "files", flush=True)
    time.sleep(2)

